begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('e5000000-0000-4000-8000-000000000001','weight-admin@example.test','{}'),('e5000000-0000-4000-8000-000000000002','weight-staff@example.test','{}');
insert into user_roles(user_id,role) values('e5000000-0000-4000-8000-000000000001','ADMIN');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated,service_role;
create temp table rr(v jsonb);grant all on rr to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Weight','Family',null,'weight@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Weight Patient','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'otherpet',id from save_patient(null,(select id from fx where k='client'),null,'Other Patient','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values('e5100000-0000-4000-8000-000000000001','https://api.trial.ezyvet.com','weight-site','animal','77','{"id":77,"contact_id":8}','animal-hash','e5000000-0000-4000-8000-000000000001');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by) values('e5200000-0000-4000-8000-000000000001',gen_random_uuid(),'mapping-hash','https://api.trial.ezyvet.com','weight-site','animal','77','e5100000-0000-4000-8000-000000000001',1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Fixture reviewed mapping','e5000000-0000-4000-8000-000000000001');
set local role service_role;
select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','weight-site','healthstatus','https://api.trial.ezyvet.com')$$,'23514',null,'Generic import cannot bypass required patient mapping');
select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','weight-site','diagnostic','https://api.trial.ezyvet.com')$$,'23514',null,'Misleading diagnostic list run disabled');
select throws_ok($$select claim_ezyvet_weight_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','other-site','https://api.trial.ezyvet.com','e5200000-0000-4000-8000-000000000001')$$,'42501',null,'Source-site mismatch denied');
insert into rr select claim_ezyvet_weight_import('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','weight-site','https://api.trial.ezyvet.com','e5200000-0000-4000-8000-000000000001');
select is((select v->>'animal_external_id' from rr),'77','Patient filter derived from reviewed mapping');
select throws_ok($$select stage_ezyvet_import_page('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from rr),1,true,'[{"external_id":"9","payload":{"id":9,"animal_id":999}}]')$$,'23514',null,'Wrong-patient provider result rejected');
select stage_ezyvet_import_page('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from rr),1,true,'[{"external_id":"9","payload":{"id":9,"animal_id":77,"active":"true","weight":"12.3","weight_unit":"kg","timestamp":"1788267600"}},{"external_id":"10","payload":{"id":10,"animal_id":77,"active":true,"weight":"15","weight_unit":"kg","timestamp":"1788267600"}}]');
insert into fx select 'source',id from ezyvet_import_snapshots where resource='healthstatus' and external_id='9' and source_site_uid='weight-site';
insert into fx select 'source2',id from ezyvet_import_snapshots where resource='healthstatus' and external_id='10' and source_site_uid='weight-site';
select throws_ok($$select approve_ezyvet_weight(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001',(select id from fx where k='source'),'hash',1,'e5200000-0000-4000-8000-000000000001',1,'create',null,12.3,'kg','2026-09-01',true,'Reviewed historical weight')$$,'42501',null,'Service cannot approve chart changes');
reset role;
create function pg_temp.approve_weight(request uuid,source uuid,weight numeric default 12.3,unit text default 'kg',measured date default '2026-09-01',target uuid default null) returns uuid language plpgsql as $$
declare s public.ezyvet_import_snapshots;payload jsonb;a public.ezyvet_weight_approvals;begin
 select * into strict s from ezyvet_import_snapshots where id=source;
 payload:=jsonb_build_object('snapshot_id',source,'expected_hash',s.payload_hash,'head_version',1,'animal_link_id','e5200000-0000-4000-8000-000000000001','patient_version',1,'action',case when target is null then 'create' else 'link' end,'weight_id',target,'weight',weight,'unit',unit,'measured_at',measured,'reason','Reviewed historical measurement');
 perform prepare_ezyvet_weight_request(request,source,payload);
 a:=approve_ezyvet_weight(request,auth.uid(),source,s.payload_hash,1,'e5200000-0000-4000-8000-000000000001',1,case when target is null then 'create' else 'link' end,target,weight,unit,measured,true,'Reviewed historical measurement');return a.weight_id;
end $$;
set local role authenticated;
select is((select count(*) from search_ezyvet_weight_patients('Weight')),1::bigint,'Search only returns mapped patients');
select is((select count(*) from list_ezyvet_weight_candidates('e5200000-0000-4000-8000-000000000001')),2::bigint,'Bounded patient observations available');
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),(select id from fx where k='source'),12.3,'unknown')$$,'23514',null,'Unknown units cannot enter primary chart');
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),(select id from fx where k='source'),'NaN','kg')$$,'23514',null,'Nonfinite source correction rejected');
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),(select id from fx where k='source'),12.3,'kg','infinity')$$,'23514',null,'Invalid dates rejected');
select throws_ok($$select approve_ezyvet_weight(gen_random_uuid(),auth.uid(),(select id from fx where k='source'),'hash',1,'e5200000-0000-4000-8000-000000000001',1,'create',null,12.3,'kg','2026-09-01',true,'Reviewed historical weight')$$,'42501',null,'Direct approval cannot bypass durable preparation');
insert into fx select 'weight',pg_temp.approve_weight('e5400000-0000-4000-8000-000000000001',(select id from fx where k='source'));
select is(pg_temp.approve_weight('e5400000-0000-4000-8000-000000000001',(select id from fx where k='source')),(select id from fx where k='weight'),'Lost response replay returns original weight');
select is((select count(*) from patient_weights where pet_id=(select id from fx where k='pet')),1::bigint,'Exactly one weight created');
select is((select source_record_id from read_weight_import_provenance((select id from fx where k='pet'),array[(select id from fx where k='weight')])),'9','Primary chart receives source provenance');
select is((select count(*) from read_weight_import_provenance((select id from fx where k='otherpet'),array[(select id from fx where k='weight')])),0::bigint,'Provenance does not cross patient boundary');
select throws_ok($$update patient_weights set weight=100 where id=(select id from fx where k='weight')$$,'42501',null,'Imported local weight remains immutable');
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),(select id from fx where k='source'))$$,'23505',null,'Different approval cannot duplicate source identity');
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),(select id from fx where k='source2'),15,'kg','2026-09-01',(select id from fx where k='weight'))$$,'23514',null,'Linking requires exact reviewed values');
select is(pg_temp.approve_weight('e5400000-0000-4000-8000-000000000002',(select id from fx where k='source2'),12.3,'kg','2026-09-01',(select id from fx where k='weight')),(select id from fx where k='weight'),'Explicit link preserves existing measurement');
select is((select count(*) from patient_weights where pet_id=(select id from fx where k='pet')),1::bigint,'Link does not add or update weight');
select is((resolve_ezyvet_weight_request('e5400000-0000-4000-8000-000000000001',(select id from fx where k='source'),false)->>'approved'),'true','Receipt acknowledgement reports completed approval');
select resolve_ezyvet_weight_request('e5400000-0000-4000-8000-000000000003',(select id from fx where k='source'),true);
select throws_ok($$select prepare_ezyvet_weight_request('e5400000-0000-4000-8000-000000000003',(select id from fx where k='source'),jsonb_build_object('snapshot_id',(select id from fx where k='source')))$$,'42501',null,'Discarded unknown preparation cannot revive late');
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values('e5500000-0000-4000-8000-000000000001','https://api.trial.ezyvet.com','weight-site','healthstatus','9','{"id":9,"animal_id":77,"active":true,"weight":"12.9","weight_unit":"kg","timestamp":"1788267600"}','corrected-source-hash','e5000000-0000-4000-8000-000000000001');
insert into ezyvet_import_pages(run_id,page,item_count) values('e5300000-0000-4000-8000-000000000001',2,1);
insert into ezyvet_import_page_items(run_id,page,snapshot_id) values('e5300000-0000-4000-8000-000000000001',2,'e5500000-0000-4000-8000-000000000001');
set local role authenticated;
select throws_ok($$select pg_temp.approve_weight(gen_random_uuid(),'e5500000-0000-4000-8000-000000000001',12.9)$$,'40001',null,'Stale source head rejected');
select lives_ok($$select review_ezyvet_weight_change('e5600000-0000-4000-8000-000000000001','e5400000-0000-4000-8000-000000000001','e5500000-0000-4000-8000-000000000001',2,'Reviewed discrepancy; retain approved local history')$$,'Changed source explicitly reviewed without replacing chart');
select lives_ok($$select review_ezyvet_weight_change('e5600000-0000-4000-8000-000000000001','e5400000-0000-4000-8000-000000000001','e5500000-0000-4000-8000-000000000001',2,'Reviewed discrepancy; retain approved local history')$$,'Source-review retry idempotent');
select is((select weight from patient_weights where id=(select id from fx where k='weight')),12.3::numeric,'Corrected source never overwrites approved local weight');
select is((select source_weight from read_weight_import_provenance((select id from fx where k='pet'),array[(select id from fx where k='weight')]) where source_record_id='9'),'12.3','Chart provenance keeps the exact approved original snapshot');
select is((select count(*) from clinical_encounters where pet_id=(select id from fx where k='pet')),0::bigint,'No encounter or signature fabricated by historical import');

reset role;
insert into record_release_policy(id,enabled,accepted_by,accepted_at,acceptance_reference,accepted_schema_version) values(true,true,'Fixture',now(),'SYNTHETIC ONLY',3);
create temp table release_data(k text primary key,v jsonb);grant all on release_data to authenticated;
set local role authenticated;
create function pg_temp.weight_preview() returns jsonb language sql as $$select preview_record_release_v4((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','weight@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='weight'))))$$;
create function pg_temp.weight_confirm(i uuid,p jsonb) returns record_releases language sql as $$select confirm_record_release(i,(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','weight@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='weight'))),p->'snapshot',p->>'source_hash',true)$$;
insert into release_data values('v4',pg_temp.weight_preview());
select is((select v#>>'{snapshot,schema_version}' from release_data where k='v4'),'4','Weight preview explicitly upgrades to v4');
select is((select jsonb_array_length(v#>'{snapshot,weights,0,import_provenance}') from release_data where k='v4'),2,'All source associations frozen, not only first');
select ok((select v::text like '%"action": "create"%' and v::text like '%"action": "link"%' from release_data where k='v4'),'Create/link provenance distinction retained');
select ok((select v::text like '%Reviewed discrepancy; retain approved local history%' from release_data where k='v4'),'Source review reason frozen');
select is((select v#>>'{snapshot,weights,0,weight}' from release_data where k='v4'),'12.3','Reviewed measurement unchanged by changed source');
select throws_ok($$select pg_temp.weight_confirm(gen_random_uuid(),(select v from release_data where k='v4'))$$,'42501',null,'v3 acceptance cannot approve v4 form');
insert into release_data select 'v3',preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','weight@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='weight'))));
select throws_ok($$select pg_temp.weight_confirm(gen_random_uuid(),(select v from release_data where k='v3'))$$,'23514',null,'Old UI cannot confirm undisplayed provenance');
select throws_ok($$select release_preview_v3_internal(null,null,null,null,null)$$,'42501',null,'Staff cannot call private legacy preview');
select throws_ok($$select release_preview_internal(null,null,null,null,null)$$,'42501',null,'Staff cannot call private v4 preview');
select throws_ok($$select preview_record_release_v4((select id from fx where k='otherpet'),(select id from fx where k='client'),'EMAIL','weight@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='weight'))))$$,'23514',null,'Cross patient provenance denied');
reset role;
update record_release_policy set accepted_schema_version=4;
with added as (insert into record_releases(id,pet_id,client_id,channel,recipient,selection,snapshot,source_hash,request,created_by) select gen_random_uuid(),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','weight@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='weight'))),v->'snapshot',v->>'source_hash','{}','e5000000-0000-4000-8000-000000000001' from release_data where k='v3' returning id) insert into fx select 'legacy-release',id from added;
insert into record_release_sources(release_id,source_kind,source_id) values((select id from fx where k='legacy-release'),'weight',(select id from fx where k='weight'));
set local role authenticated;
insert into fx select 'release',id from pg_temp.weight_confirm(gen_random_uuid(),(select v from release_data where k='v4'));
select is(read_record_release((select id from fx where k='release'))->>'eligible','true','v4 initially eligible');
reset role;
insert into conversations(id,client_id) values('e5700000-0000-4000-8000-000000000001',(select id from fx where k='client'));
set local role authenticated;
select lives_ok($$select prepare_release_email('e5700000-0000-4000-8000-000000000002',(select id from fx where k='release'),'e5700000-0000-4000-8000-000000000001','Reviewed weights','Historical source report',(select v->>'source_hash' from release_data where k='v4'))$$,'V4 email preparation checks exact provenance');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select release_email_capture_context('e5700000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001')$$,'V4 capture context validates current provenance under service wrapper');
select capture_release_email_payload('e5700000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001',jsonb_build_object('from','care@example.test','reply_to','care@example.test','to',jsonb_build_array('weight@example.test'),'subject','Reviewed weights','text','Historical source report','attachments',jsonb_build_array(jsonb_build_object('filename','medical-records-'||(select id::text from fx where k='release')||'.html','content_type','text/html','content',encode(convert_to('<!doctype html><h1>Fixture</h1>','UTF8'),'base64'))))::text);
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'outbox',id from enqueue_release_email('e5700000-0000-4000-8000-000000000002',recover_release_email((select id from fx where k='release'))->>'payload_hash',true);
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into fx select 'lease',lease_token from claim_communication();
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select review_ezyvet_weight_change(gen_random_uuid(),'e5400000-0000-4000-8000-000000000001','e5500000-0000-4000-8000-000000000001',2,'Additional source review without altering weight');
select is(read_record_release((select id from fx where k='release'))->>'eligible','false','New source review invalidates v4');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select release_email_capture_context('e5700000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001')$$,'42501',null,'Changed provenance denies new capture context');
select is((start_communication_attempt((select id from fx where k='outbox'),(select id from fx where k='lease'),'{"from":"care@example.test","reply_to":"care@example.test"}')).state,'failed','Changed provenance blocks final provider preflight without a send');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);

select is((select snapshot from record_releases where id=(select id from fx where k='release')),(select v->'snapshot' from release_data where k='v4'),'Confirmed snapshot never mutated');
select throws_ok($$select pg_temp.weight_confirm(gen_random_uuid(),(select v from release_data where k='v4'))$$,'40001',null,'Stale provenance review hash rejected');
select is((pg_temp.weight_confirm((select id from fx where k='release'),(select v from release_data where k='v4'))).id,(select id from fx where k='release'),'Exact lost-confirm response retry still returns original receipt');
select ok((list_record_release_sources((select id from fx where k='pet'),0)->>'policy_v4_accepted')::boolean,'UI receives explicit v4 policy gate');
select is(read_record_release((select id from fx where k='legacy-release'))->>'eligible','true','Legacy v3 eligibility preserved despite provenance append');
select is((select snapshot from record_releases where id=(select id from fx where k='legacy-release')),(select v->'snapshot' from release_data where k='v3'),'Legacy v3 frozen content unchanged');
insert into fx select 'release-before-source-change',id from pg_temp.weight_confirm(gen_random_uuid(),pg_temp.weight_preview());
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values('e5500000-0000-4000-8000-000000000002','https://api.trial.ezyvet.com','weight-site','healthstatus','9','{"id":9,"animal_id":77,"active":false,"weight":"13","weight_unit":"kg","timestamp":"1788267600"}','new-source-hash','e5000000-0000-4000-8000-000000000001');
insert into ezyvet_import_pages(run_id,page,item_count) values('e5300000-0000-4000-8000-000000000001',3,1);
insert into ezyvet_import_page_items(run_id,page,snapshot_id) values('e5300000-0000-4000-8000-000000000001',3,'e5500000-0000-4000-8000-000000000002');
set local role authenticated;
select is(read_record_release((select id from fx where k='release-before-source-change'))->>'eligible','false','External source head change invalidates v4 before review');
select is(read_record_release((select id from fx where k='legacy-release'))->>'eligible','true','External source head change preserves legacy eligibility');
select ok(pg_temp.weight_preview()::text like '%"latest_source_reviewed": false%','Unreviewed changed source explicitly labeled');
select * from finish();
rollback;
